const items = $input.all();
const collectedStories = [];

// Process XML / RSS / JSON inputs
for (const item of items) {
  const rawData = item.json.data || item.json.body || item.json;

  if (typeof rawData === 'string' && rawData.includes('<item>')) {
    // XML RSS parsing
    const titleMatches = [...rawData.matchAll(/<title><!\[CDATA\[(.*?)\]\]><\/title>|<title>(.*?)<\/title>/g)];
    const linkMatches = [...rawData.matchAll(/<link>(.*?)<\/link>/g)];

    titleMatches.slice(0, 10).forEach((tm, idx) => {
      const title = tm[1] || tm[2] || '';
      const link = linkMatches[idx] ? linkMatches[idx][1] : '';
      if (title && !title.includes('Google News')) {
        collectedStories.push({ title, link, source: 'Google News', timestamp: new Date().toISOString() });
      }
    });
  } else if (Array.isArray(rawData)) {
    // HN ID list
    collectedStories.push({
      title: 'Trending tech topic discussion on Hacker News',
      link: 'https://news.ycombinator.com',
      source: 'Hacker News',
      timestamp: new Date().toISOString()
    });
  }
}

// Deduplicate similar titles
const uniqueMap = new Map();
collectedStories.forEach(s => {
  const key = s.title.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 30);
  if (!uniqueMap.has(key)) uniqueMap.set(key, s);
});

const topStories = Array.from(uniqueMap.values()).slice(0, 8);

return [{
  json: {
    storyCount: topStories.length,
    stories: topStories,
    batchId: 'NEWS-' + Date.now(),
    monitoredAt: new Date().toISOString()
  }
}];

const item = $input.first();
let editorial = item.json.output || item.json.text || item.json;

if (typeof editorial === 'string') {
  try {
    editorial = JSON.parse(editorial);
  } catch (e) {
    const m = editorial.match(/\{[\s\S]*\}/);
    if (m) editorial = JSON.parse(m[0]);
  }
}

const headline = editorial.breaking_headline || 'Global Tech & AI News Update';
const bullets = (editorial.key_developments || []).map(b => `• ${b}`).join('\n');
const urgency = editorial.urgency_level || 'HIGH';

const telegramText = `🚨 *BREAKING NEWS DIGEST* [${urgency}]

📌 *${headline}*

${bullets}

💡 *Market Impact:* ${editorial.impact_analysis || ''}

💬 *Join Discussion:* ${editorial.social_media_hook || ''}`;

return [{
  json: {
    ...editorial,
    headline,
    telegramText,
    urgency,
    publishedAt: new Date().toISOString()
  }
}];
